def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    ones=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
    # Join 1s sharing a diagonal.
    for slope in (1,-1):
        groups={}
        for r,c in ones: groups.setdefault(c-slope*r,[]).append((r,c))
        for pts in groups.values():
            if len(pts)<2: continue
            pts.sort(); (r0,c0),(r1,c1)=pts[0],pts[-1]
            r,c=r0,c0
            while True:
                if grid[r][c]!=6: out[r][c]=1
                if (r,c)==(r1,c1): break
                r+=1; c+=slope
    # A single 6 marker extends up-left only when paired with a 1 on
    # its down-right diagonal; two 6 markers fill their connecting segment.
    sixes=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==6]
    for r,c in sixes:
        rr,cc=r-1,c-1
        while rr>=0 and cc>=0:
            if grid[rr][cc]==1:
                rr-=1;cc-=1
                continue
            if any((rr+i,cc+i) in sixes for i in range(1, min(h-rr,w-cc))):
                rr-=1;cc-=1
                continue
            out[rr][cc]=6
            rr-=1;cc-=1
    return out

